/* Minimal PHP runtime for assembly generated by il2asm.php.
 *
 * Values are heap cells (`pv`) with no reference counting: the runtime never
 * frees, exactly like the .NET shim. Arrays are ordered hash maps, which is
 * what PHP arrays are. A translated script therefore performs the real routing,
 * comparisons, array writes and JSON work; this file supplies only the
 * primitive operations.
 *
 * The request layer is a dry run: headers and status are recorded in memory,
 * `exit` unwinds with longjmp, and the session file lives in a process-local
 * buffer. No HTTP server is involved.
 */
#include "php.h"

#include <ctype.h>
#include <setjmp.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* ------------------------------------------------------------- allocation */
static void *xalloc(size_t n)
{
    void *p = calloc(1, n ? n : 1);
    if (!p) {
        fprintf(stderr, "php shim: out of memory\n");
        abort();
    }
    return p;
}

/* ----------------------------------------------------------------- values */
typedef struct pventry {
    char *key;
    pv val;
    struct pventry *next;
} pventry;

struct pvarr {
    pventry *head, *tail;
    long next_index;
};

struct pv php_null_obj = { PV_NULL, { 0 } };

static pv new_pv(pv_type t)
{
    pv v = xalloc(sizeof(*v));
    v->t = t;
    return v;
}

pv php_null(void) { return &php_null_obj; }
pv php_true(void) { return php_bool(1); }
pv php_false(void) { return php_bool(0); }

pv php_bool(int b)
{
    pv v = new_pv(PV_BOOL);
    v->u.b = b != 0;
    return v;
}

pv php_int(long i)
{
    pv v = new_pv(PV_INT);
    v->u.i = i;
    return v;
}

pv php_double(double d)
{
    pv v = new_pv(PV_DOUBLE);
    v->u.d = d;
    return v;
}

pv php_str(const char *s)
{
    return php_strn(s ? s : "", s ? strlen(s) : 0);
}

pv php_strn(const char *s, size_t n)
{
    pv v = new_pv(PV_STR);
    v->u.s.p = xalloc(n + 1);
    if (n) {
        memcpy(v->u.s.p, s, n);
    }
    v->u.s.p[n] = '\0';
    v->u.s.n = n;
    return v;
}

static pv norm(pv v) { return v ? v : &php_null_obj; }

int php_is_null(pv v) { return norm(v)->t == PV_NULL; }
int php_is_array(pv v) { return norm(v)->t == PV_ARR; }
int php_is_string(pv v) { return norm(v)->t == PV_STR; }
int php_is_bool(pv v) { return norm(v)->t == PV_BOOL; }
int php_is_int(pv v) { return norm(v)->t == PV_INT; }
int php_is_double(pv v) { return norm(v)->t == PV_DOUBLE; }

int php_truthy(pv v)
{
    v = norm(v);
    switch (v->t) {
    case PV_NULL:   return 0;
    case PV_BOOL:   return v->u.b;
    case PV_INT:    return v->u.i != 0;
    case PV_DOUBLE: return v->u.d != 0.0;
    case PV_STR:
        return v->u.s.n > 0 && !(v->u.s.n == 1 && v->u.s.p[0] == '0');
    case PV_ARR:    return v->u.a->head != NULL;
    default:        return 1;
    }
}

int php_empty(pv v) { return !php_truthy(v); }

pv php_not(pv v) { return php_bool(!php_truthy(v)); }
pv php_isset_pv(pv v) { return php_bool(norm(v)->t != PV_NULL); }
pv php_empty_pv(pv v) { return php_bool(php_empty(v)); }

const char *php_cstr(pv v)
{
    /* A ring keeps two conversions live at once, as in php_cstr(a)+php_cstr(b). */
    static char buf[4][64];
    static unsigned slot;
    char *b = buf[slot++ & 3];
    v = norm(v);
    switch (v->t) {
    case PV_NULL: return "";
    case PV_BOOL: return v->u.b ? "1" : "";
    case PV_STR:  return v->u.s.p;
    case PV_INT:
        snprintf(b, 64, "%ld", v->u.i);
        return b;
    case PV_DOUBLE:
        snprintf(b, 64, "%g", v->u.d);
        return b;
    case PV_ARR:  return "Array";
    default:      return "Object";
    }
}

static double as_double(pv v)
{
    v = norm(v);
    switch (v->t) {
    case PV_INT:    return (double)v->u.i;
    case PV_DOUBLE: return v->u.d;
    case PV_BOOL:   return v->u.b ? 1.0 : 0.0;
    default:        return strtod(php_cstr(v), NULL);
    }
}

static long as_long(pv v)
{
    v = norm(v);
    if (v->t == PV_INT) {
        return v->u.i;
    }
    return (long)as_double(v);
}

static int numeric_like(pv v)
{
    v = norm(v);
    if (v->t == PV_INT || v->t == PV_DOUBLE) {
        return 1;
    }
    if (v->t == PV_STR && v->u.s.n) {
        char *end = NULL;
        strtod(v->u.s.p, &end);
        return end && *end == '\0';
    }
    return 0;
}

/* ---------------------------------------------------------------- strings */
size_t php_strlen_raw(pv v) { return norm(v)->t == PV_STR ? v->u.s.n : 0; }

pv php_strlen(pv v)
{
    return php_int((long)php_strlen_raw(v));
}

pv php_concat(pv a, pv b)
{
    const char *x = php_cstr(a);
    const char *y = php_cstr(b);
    size_t nx = strlen(x), ny = strlen(y);
    pv v = new_pv(PV_STR);
    v->u.s.p = xalloc(nx + ny + 1);
    memcpy(v->u.s.p, x, nx);
    memcpy(v->u.s.p + nx, y, ny);
    v->u.s.p[nx + ny] = '\0';
    v->u.s.n = nx + ny;
    return v;
}

pv php_add(pv a, pv b)
{
    if (norm(a)->t == PV_DOUBLE || norm(b)->t == PV_DOUBLE) {
        return php_double(as_double(a) + as_double(b));
    }
    return php_int(as_long(a) + as_long(b));
}

pv php_sub(pv a, pv b)
{
    if (norm(a)->t == PV_DOUBLE || norm(b)->t == PV_DOUBLE) {
        return php_double(as_double(a) - as_double(b));
    }
    return php_int(as_long(a) - as_long(b));
}

static int str_cmp(pv a, pv b)
{
    return strcmp(php_cstr(a), php_cstr(b));
}

pv php_ident(pv a, pv b)
{
    a = norm(a); b = norm(b);
    if (a->t != b->t) {
        return php_false();
    }
    switch (a->t) {
    case PV_NULL:   return php_true();
    case PV_BOOL:   return php_bool(a->u.b == b->u.b);
    case PV_INT:    return php_bool(a->u.i == b->u.i);
    case PV_DOUBLE: return php_bool(a->u.d == b->u.d);
    case PV_STR:    return php_bool(a->u.s.n == b->u.s.n &&
                                    !memcmp(a->u.s.p, b->u.s.p, a->u.s.n));
    default:        return php_bool(a == b);
    }
}

pv php_nident(pv a, pv b)
{
    return php_not(php_ident(a, b));
}

pv php_eq(pv a, pv b)
{
    a = norm(a); b = norm(b);
    if (a->t == PV_NULL && b->t == PV_NULL) return php_true();
    if (a->t == PV_BOOL || b->t == PV_BOOL) {
        return php_bool(php_truthy(a) == php_truthy(b));
    }
    if (numeric_like(a) && numeric_like(b)) {
        return php_bool(as_double(a) == as_double(b));
    }
    return php_bool(str_cmp(a, b) == 0);
}

pv php_ne(pv a, pv b) { return php_not(php_eq(a, b)); }

pv php_gt(pv a, pv b)
{
    if (numeric_like(a) && numeric_like(b)) return php_bool(as_double(a) > as_double(b));
    return php_bool(str_cmp(a, b) > 0);
}

pv php_lt(pv a, pv b)
{
    if (numeric_like(a) && numeric_like(b)) return php_bool(as_double(a) < as_double(b));
    return php_bool(str_cmp(a, b) < 0);
}

pv php_ge(pv a, pv b) { return php_not(php_lt(a, b)); }
pv php_le(pv a, pv b) { return php_not(php_gt(a, b)); }

/* ----------------------------------------------------------------- arrays */
pv php_arr(void)
{
    pv v = new_pv(PV_ARR);
    v->u.a = xalloc(sizeof(struct pvarr));
    return v;
}

static pventry *arr_find(pv arr, const char *key)
{
    if (norm(arr)->t != PV_ARR) {
        return NULL;
    }
    for (pventry *e = arr->u.a->head; e; e = e->next) {
        if (!strcmp(e->key, key)) {
            return e;
        }
    }
    return NULL;
}

void php_arr_set(pv arr, pv key, pv val)
{
    arr = norm(arr);
    if (arr->t != PV_ARR) {
        return;
    }
    char buf[32];
    const char *k;
    if (norm(key)->t == PV_NULL) {
        snprintf(buf, sizeof buf, "%ld", arr->u.a->next_index);
        k = buf;
    } else {
        k = php_cstr(key);
    }
    pventry *e = arr_find(arr, k);
    if (e) {
        e->val = norm(val);
        return;
    }
    e = xalloc(sizeof(*e));
    e->key = strdup(k);
    e->val = norm(val);
    if (arr->u.a->tail) {
        arr->u.a->tail->next = e;
    } else {
        arr->u.a->head = e;
    }
    arr->u.a->tail = e;
    char *end = NULL;
    long idx = strtol(k, &end, 10);
    if (end && *end == '\0' && idx >= arr->u.a->next_index) {
        arr->u.a->next_index = idx + 1;
    }
}

void php_arr_push(pv arr, pv val) { php_arr_set(arr, php_null(), val); }

pv php_arr_get(pv arr, pv key)
{
    pventry *e = arr_find(arr, php_cstr(key));
    return e ? e->val : php_null();
}

int php_arr_has(pv arr, pv key) { return arr_find(arr, php_cstr(key)) != NULL; }

pv php_arr_isset(pv arr, pv key)
{
    pventry *e = arr_find(arr, php_cstr(key));
    return php_bool(e && norm(e->val)->t != PV_NULL);
}

pv php_array_key_exists(pv key, pv arr) { return php_bool(php_arr_has(arr, key)); }

long php_count(pv v)
{
    v = norm(v);
    if (v->t != PV_ARR) {
        return v->t == PV_NULL ? 0 : 1;
    }
    long n = 0;
    for (pventry *e = v->u.a->head; e; e = e->next) {
        n++;
    }
    return n;
}

pv php_count_pv(pv v) { return php_int(php_count(v)); }

/* -------------------------------------------------------------- iteration */
struct php_iter {
    pventry *cur;
};

void *php_iter_begin(pv arr)
{
    struct php_iter *it = xalloc(sizeof(*it));
    arr = norm(arr);
    it->cur = arr->t == PV_ARR ? arr->u.a->head : NULL;
    return it;
}

pv *php_iter_next(void *handle)
{
    struct php_iter *it = handle;
    if (!it || !it->cur) {
        return NULL;
    }
    pventry *e = it->cur;
    it->cur = e->next;
    return &e->val;
}

/* --------------------------------------------------------------- closures */
struct php_env {
    pv slot[2];
};

pv php_callable(void *fn, void *env)
{
    pv v = new_pv(PV_CALL);
    v->u.c.fn = fn;
    v->u.c.env = env;
    return v;
}

void *php_env1(pv a)
{
    struct php_env *e = xalloc(sizeof(*e));
    e->slot[0] = norm(a);
    return e;
}

void *php_env2(pv a, pv b)
{
    struct php_env *e = xalloc(sizeof(*e));
    e->slot[0] = norm(a);
    e->slot[1] = norm(b);
    return e;
}

pv php_env_get(void *env, long idx)
{
    struct php_env *e = env;
    if (!e || idx < 0 || idx > 1) {
        return php_null();
    }
    return e->slot[idx];
}

pv php_call1(pv cb, pv a0)
{
    cb = norm(cb);
    if (cb->t != PV_CALL) {
        return php_null();
    }
    pv (*fn)(void *, pv) = (pv (*)(void *, pv))cb->u.c.fn;
    return fn(cb->u.c.env, a0);
}

/* ------------------------------------------------------------------- JSON */
static void buf_add(char **buf, size_t *len, size_t *cap, const char *s, size_t n)
{
    if (*len + n + 1 > *cap) {
        size_t want = (*len + n + 1) * 2;
        char *p = realloc(*buf, want);
        if (!p) abort();
        *buf = p;
        *cap = want;
    }
    memcpy(*buf + *len, s, n);
    *len += n;
    (*buf)[*len] = '\0';
}

static void buf_str(char **b, size_t *l, size_t *c, const char *s)
{
    buf_add(b, l, c, s, strlen(s));
}

static int is_list(pv v)
{
    long i = 0;
    for (pventry *e = v->u.a->head; e; e = e->next, i++) {
        char want[32];
        snprintf(want, sizeof want, "%ld", i);
        if (strcmp(e->key, want)) {
            return 0;
        }
    }
    return 1;
}

static void json_enc(pv v, int unescaped_slashes, char **b, size_t *l, size_t *c)
{
    v = norm(v);
    char tmp[64];
    switch (v->t) {
    case PV_NULL: buf_str(b, l, c, "null"); break;
    case PV_BOOL: buf_str(b, l, c, v->u.b ? "true" : "false"); break;
    case PV_INT:
        snprintf(tmp, sizeof tmp, "%ld", v->u.i);
        buf_str(b, l, c, tmp);
        break;
    case PV_DOUBLE:
        snprintf(tmp, sizeof tmp, "%.10g", v->u.d);
        buf_str(b, l, c, tmp);
        break;
    case PV_STR:
        buf_add(b, l, c, "\"", 1);
        for (size_t i = 0; i < v->u.s.n; i++) {
            unsigned char ch = (unsigned char)v->u.s.p[i];
            switch (ch) {
            case '"':  buf_str(b, l, c, "\\\""); break;
            case '\\': buf_str(b, l, c, "\\\\"); break;
            case '\n': buf_str(b, l, c, "\\n"); break;
            case '\r': buf_str(b, l, c, "\\r"); break;
            case '\t': buf_str(b, l, c, "\\t"); break;
            case '/':
                buf_str(b, l, c, unescaped_slashes ? "/" : "\\/");
                break;
            default:
                if (ch < 0x20) {
                    snprintf(tmp, sizeof tmp, "\\u%04x", ch);
                    buf_str(b, l, c, tmp);
                } else {
                    buf_add(b, l, c, (char *)&ch, 1);
                }
            }
        }
        buf_add(b, l, c, "\"", 1);
        break;
    case PV_ARR: {
        int list = is_list(v);
        buf_add(b, l, c, list ? "[" : "{", 1);
        long i = 0;
        for (pventry *e = v->u.a->head; e; e = e->next, i++) {
            if (i) buf_add(b, l, c, ",", 1);
            if (!list) {
                json_enc(php_str(e->key), unescaped_slashes, b, l, c);
                buf_add(b, l, c, ":", 1);
            }
            json_enc(e->val, unescaped_slashes, b, l, c);
        }
        buf_add(b, l, c, list ? "]" : "}", 1);
        break;
    }
    default:
        buf_str(b, l, c, "null");
    }
}

pv php_json_encode(pv v, pv flags)
{
    char *b = NULL;
    size_t l = 0, c = 0;
    buf_add(&b, &l, &c, "", 0);
    json_enc(v, php_truthy(flags) && as_long(flags) == 64, &b, &l, &c);
    pv out = php_strn(b, l);
    free(b);
    return out;
}

typedef struct {
    const char *s;
    size_t n, i;
} jparser;

static void jskip(jparser *p)
{
    while (p->i < p->n && isspace((unsigned char)p->s[p->i])) p->i++;
}

static pv jvalue(jparser *p);

static pv jstring(jparser *p)
{
    p->i++; /* opening quote */
    char *out = xalloc(p->n + 1);
    size_t k = 0;
    while (p->i < p->n && p->s[p->i] != '"') {
        char ch = p->s[p->i++];
        if (ch == '\\' && p->i < p->n) {
            char e = p->s[p->i++];
            switch (e) {
            case 'n': ch = '\n'; break;
            case 'r': ch = '\r'; break;
            case 't': ch = '\t'; break;
            case 'b': ch = '\b'; break;
            case 'f': ch = '\f'; break;
            case 'u': {
                unsigned v = 0;
                for (int k2 = 0; k2 < 4 && p->i < p->n; k2++) {
                    char h = p->s[p->i++];
                    v = v * 16 + (h >= '0' && h <= '9' ? h - '0'
                                : h >= 'a' && h <= 'f' ? h - 'a' + 10
                                : h >= 'A' && h <= 'F' ? h - 'A' + 10 : 0);
                }
                ch = v < 0x80 ? (char)v : '?';
                break;
            }
            default: ch = e;
            }
        }
        out[k++] = ch;
    }
    if (p->i < p->n && p->s[p->i] == '"') p->i++;
    pv v = php_strn(out, k);
    free(out);
    return v;
}

static pv jvalue(jparser *p)
{
    jskip(p);
    if (p->i >= p->n) return php_null();
    char ch = p->s[p->i];
    if (ch == '"') return jstring(p);
    if (ch == '{') {
        p->i++;
        pv arr = php_arr();
        jskip(p);
        if (p->i < p->n && p->s[p->i] == '}') { p->i++; return arr; }
        for (;;) {
            jskip(p);
            pv key = jstring(p);
            jskip(p);
            if (p->i < p->n && p->s[p->i] == ':') p->i++;
            pv val = jvalue(p);
            php_arr_set(arr, key, val);
            jskip(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == '}') p->i++;
            break;
        }
        return arr;
    }
    if (ch == '[') {
        p->i++;
        pv arr = php_arr();
        jskip(p);
        if (p->i < p->n && p->s[p->i] == ']') { p->i++; return arr; }
        for (;;) {
            php_arr_push(arr, jvalue(p));
            jskip(p);
            if (p->i < p->n && p->s[p->i] == ',') { p->i++; continue; }
            if (p->i < p->n && p->s[p->i] == ']') p->i++;
            break;
        }
        return arr;
    }
    if (!strncmp(p->s + p->i, "true", 4))  { p->i += 4; return php_true(); }
    if (!strncmp(p->s + p->i, "false", 5)) { p->i += 5; return php_false(); }
    if (!strncmp(p->s + p->i, "null", 4))  { p->i += 4; return php_null(); }
    {
        char *end = NULL;
        double d = strtod(p->s + p->i, &end);
        if (end && end > p->s + p->i) {
            int is_int = 1;
            for (const char *q = p->s + p->i; q < end; q++) {
                if (*q == '.' || *q == 'e' || *q == 'E') { is_int = 0; break; }
            }
            p->i = (size_t)(end - p->s);
            return is_int ? php_int((long)d) : php_double(d);
        }
    }
    p->i++;
    return php_null();
}

pv php_json_decode(pv v, pv assoc)
{
    (void)assoc;
    v = norm(v);
    if (v->t != PV_STR) {
        return php_null();
    }
    jparser p = { v->u.s.p, v->u.s.n, 0 };
    return jvalue(&p);
}

/* --------------------------------------------------------------- requests */
static const char *req_method = "GET";
static const char *req_uri = "/";
static const char *req_body = "";
static const char *req_query = "";

static long resp_status = 200;
static char *resp_body;
static size_t resp_len;

static jmp_buf req_jmp;
static int req_active;

int php_execute(void (*entry)(void), const char *method, const char *uri,
                const char *body, const char *query)
{
    req_method = method ? method : "GET";
    req_uri = uri ? uri : "/";
    req_body = body ? body : "";
    req_query = query ? query : "";
    resp_status = 200;
    free(resp_body);
    resp_body = NULL;
    resp_len = 0;
    req_active = 1;

    if (setjmp(req_jmp) == 0) {
        entry();
    }
    req_active = 0;
    return (int)resp_status;
}

long php_response_status(void) { return resp_status; }
const char *php_response_body(void) { return resp_body ? resp_body : ""; }

void php_http_code(pv v)
{
    if (php_truthy(v)) {
        resp_status = as_long(v);
    }
}

static void resp_add(const char *s, size_t n)
{
    char *p = realloc(resp_body, resp_len + n + 1);
    if (!p) abort();
    resp_body = p;
    memcpy(resp_body + resp_len, s, n);
    resp_len += n;
    resp_body[resp_len] = '\0';
}

void php_header(pv v)
{
    /* A dry run does not transmit headers. Keep the call visible in traces. */
    (void)v;
}

void php_echo(pv v)
{
    v = norm(v);
    if (v->t == PV_STR) {
        resp_add(v->u.s.p, v->u.s.n);
    } else {
        const char *s = php_cstr(v);
        resp_add(s, strlen(s));
    }
}

void php_exit(void)
{
    if (req_active) {
        longjmp(req_jmp, 1);
    }
    exit(0);
}

pv php_server(pv name)
{
    const char *k = php_cstr(name);
    if (!strcmp(k, "REQUEST_METHOD")) return php_str(req_method);
    if (!strcmp(k, "REQUEST_URI")) return php_str(req_uri);
    return php_null();
}

static int hexval(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

/* Parse the request's query string rather than returning it verbatim. */
pv php_get(pv name)
{
    const char *want = php_cstr(name);
    const char *p = req_query;
    while (p && *p) {
        const char *eq = strchr(p, '=');
        const char *amp = strchr(p, '&');
        if (!eq || (amp && amp < eq)) {
            p = amp ? amp + 1 : NULL;
            continue;
        }
        size_t klen = (size_t)(eq - p);
        const char *vend = amp ? amp : eq + strlen(eq);
        if (strlen(want) == klen && !strncmp(p, want, klen)) {
            size_t n = (size_t)(vend - (eq + 1));
            char *out = xalloc(n + 1);
            size_t k = 0;
            for (size_t i = 0; i < n; i++) {
                char ch = eq[1 + i];
                if (ch == '+') {
                    out[k++] = ' ';
                } else if (ch == '%' && i + 2 < n && hexval(eq[2 + i]) >= 0 &&
                           hexval(eq[3 + i]) >= 0) {
                    out[k++] = (char)(hexval(eq[2 + i]) * 16 + hexval(eq[3 + i]));
                    i += 2;
                } else {
                    out[k++] = ch;
                }
            }
            pv v = php_strn(out, k);
            free(out);
            return v;
        }
        p = amp ? amp + 1 : NULL;
    }
    return php_null();
}

pv php_input(void) { return php_str(req_body); }

pv php_parse_url_path(pv u)
{
    const char *s = php_cstr(u);
    const char *q = strchr(s, '?');
    size_t n = q ? (size_t)(q - s) : strlen(s);
    return php_strn(s, n);
}

/* ---------------------------------------------------------------- file I/O */
static char *state_buf;
static size_t state_len;
static size_t state_pos;

pv php_file_get(pv path)
{
    const char *p = php_cstr(path);
    if (!strcmp(p, "php://input")) {
        return php_str(req_body);
    }
    return php_strn(state_buf ? state_buf : "", state_len);
}

pv php_fopen(pv path, pv mode)
{
    (void)path;
    (void)mode;
    state_pos = 0;
    return php_int(1);
}

pv php_fclose(pv h) { (void)h; return php_true(); }

pv php_flock(pv h, pv op) { (void)h; (void)op; return php_true(); }

pv php_rewind(pv h) { (void)h; state_pos = 0; return php_true(); }

pv php_stream_get(pv h)
{
    (void)h;
    size_t n = state_len > state_pos ? state_len - state_pos : 0;
    pv v = php_strn(state_buf ? state_buf + state_pos : "", n);
    state_pos = state_len;
    return v;
}

pv php_ftruncate(pv h, pv size)
{
    (void)h;
    (void)size;
    free(state_buf);
    state_buf = NULL;
    state_len = 0;
    state_pos = 0;
    return php_true();
}

pv php_fwrite(pv h, pv data)
{
    (void)h;
    data = norm(data);
    const char *s = php_cstr(data);
    size_t n = data->t == PV_STR ? data->u.s.n : strlen(s);
    if (state_pos > state_len) {
        state_pos = state_len;
    }
    size_t need = state_pos + n + 1;
    char *p = realloc(state_buf, need);
    if (!p) abort();
    state_buf = p;
    memcpy(state_buf + state_pos, s, n);
    state_pos += n;
    if (state_pos > state_len) {
        state_len = state_pos;
    }
    state_buf[state_len] = '\0';
    return php_int((long)n);
}

pv php_fflush(pv h) { (void)h; return php_true(); }

pv php_is_dir(pv p) { (void)p; return php_true(); }
pv php_mkdir(pv p, pv mode, pv rec) { (void)p; (void)mode; (void)rec; return php_true(); }

pv php_dirname(pv p)
{
    const char *s = php_cstr(p);
    size_t n = strlen(s);
    while (n > 1 && s[n - 1] == '/') n--;
    while (n > 0 && s[n - 1] != '/') n--;
    if (n > 0) n--;
    return php_strn(s, n ? n : 1);
}

/* ------------------------------------------------------------ misc builtins */
pv php_time(void) { return php_int((long)time(NULL)); }

pv php_microtime(pv as_float)
{
    if (php_truthy(as_float)) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        return php_double((double)ts.tv_sec + (double)ts.tv_nsec / 1e9);
    }
    return php_str("0.00000000 0");
}

pv php_random_bytes(pv n)
{
    static unsigned long seed = 0x5eed1234UL;
    long count = as_long(n);
    if (count < 0) count = 0;
    char *p = xalloc((size_t)count + 1);
    for (long i = 0; i < count; i++) {
        seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
        p[i] = (char)((seed >> 33) & 0xff);
    }
    pv v = php_strn(p, (size_t)count);
    free(p);
    return v;
}

pv php_bin2hex(pv v)
{
    v = norm(v);
    static const char hex[] = "0123456789abcdef";
    size_t n = v->t == PV_STR ? v->u.s.n : 0;
    char *out = xalloc(n * 2 + 1);
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)v->u.s.p[i];
        out[i * 2] = hex[c >> 4];
        out[i * 2 + 1] = hex[c & 15];
    }
    pv r = php_strn(out, n * 2);
    free(out);
    return r;
}

pv php_strpos(pv h, pv n)
{
    const char *s = php_cstr(h);
    const char *p = strstr(s, php_cstr(n));
    return p ? php_int((long)(p - s)) : php_false();
}

pv php_stripos(pv h, pv n)
{
    const char *s = php_cstr(h);
    const char *needle = php_cstr(n);
    size_t nl = strlen(needle);
    for (size_t i = 0; s[i]; i++) {
        if (!strncasecmp(s + i, needle, nl)) {
            return php_int((long)i);
        }
    }
    return php_false();
}

pv php_substr(pv s, pv start)
{
    const char *p = php_cstr(s);
    long i = as_long(start);
    long n = (long)strlen(p);
    if (i < 0) i = 0;
    if (i > n) i = n;
    return php_str(p + i);
}

pv php_trim(pv s)
{
    const char *p = php_cstr(s);
    while (*p && isspace((unsigned char)*p)) p++;
    size_t n = strlen(p);
    while (n && isspace((unsigned char)p[n - 1])) n--;
    return php_strn(p, n);
}

pv php_rtrim(pv s, pv chars)
{
    const char *p = php_cstr(s);
    const char *set = php_cstr(chars);
    size_t n = strlen(p);
    while (n && strchr(set, p[n - 1])) n--;
    return php_strn(p, n);
}
